{
  "findings": [
    {
      "id": "RV-01",
      "category": "stack_deploy",
      "severity": "high",
      "finding": "Ada keputusan teknis yang bertabrakan langsung dengan stack dan cara deploy yang dipakai. Serverless plus SQLite tidak cocok dengan PostgreSQL + Drizzle, dengan job terjadwal pg-boss yang butuh proses selalu hidup dan PostgreSQL, dan dengan keputusan deploy API sebagai container.",
      "evidence": "technical_decisions: \"Backend dideploy sebagai serverless function dengan database SQLite supaya gratis.\" Ini bertentangan dengan \"PostgreSQL dengan Drizzle dan drizzle-kit...\", \"Pengecekan member akan habis dan sudah habis dijalankan harian lewat pg-boss di API yang selalu hidup\", dan \"API dideploy sebagai container yang selalu hidup\".",
      "options": [
        {
          "label": "Hapus keputusan serverless + SQLite",
          "consequence": "Rencana kembali konsisten: API jalan sebagai container yang selalu hidup dengan PostgreSQL, dan pg-boss bisa menjalankan job harian. Tetap ada biaya hosting container dan database, tapi bisa ditekan dengan tier kecil."
        },
        {
          "label": "Ganti ke serverless dengan PostgreSQL terkelola dan scheduler eksternal",
          "consequence": "Biaya awal bisa lebih murah, tapi pg-boss tidak bisa dipakai apa adanya. Job harian harus dipindah ke cron eksternal, ada risiko cold start dan batas koneksi database, dan cara deploy berbeda dari standar yang dipakai."
        }
      ],
      "recommended_option": "Hapus keputusan serverless + SQLite"
    },
    {
      "id": "RV-02",
      "category": "dependency_order",
      "severity": "high",
      "finding": "Login admin (F-01) baru dijadwalkan di fase terakhir, padahal fitur lain di fase awal bergantung padanya. Pengelolaan gym dan peran tidak bisa dibangun tanpa akun dan verifikasi token.",
      "evidence": "F-02 depends_on [\"F-01\"] dan ada di phase 0 (feature_ids [\"F-02\",\"F-03\"]). F-01 justru ada di phase 3 (feature_ids [\"F-07\",\"F-08\",\"F-90\",\"F-01\"]). Goal phase 0 sendiri menyebut \"login admin\", tapi F-01 tidak ada di daftarnya.",
      "options": [
        {
          "label": "Pindahkan F-01 ke fase 0",
          "consequence": "Urutan jadi benar: login dan verifikasi token siap dulu, baru peran, paket, dan data member dibangun di atasnya. Fase 0 jadi sedikit lebih besar."
        },
        {
          "label": "Buat fase auth terpisah sebelum fase 0 yang sekarang",
          "consequence": "Auth bisa diuji tuntas sendiri, tapi jumlah fase bertambah dan fitur yang terlihat oleh pemilik gym muncul lebih lambat."
        }
      ],
      "recommended_option": "Pindahkan F-01 ke fase 0"
    },
    {
      "id": "RV-03",
      "category": "security",
      "severity": "high",
      "finding": "Karena login baru ada di fase 3, endpoint data member (nama, nomor HP), perpanjangan, bahkan ekspor dan hapus permanen akan dibangun dan mungkin sudah terbuka selama fase 0-2 tanpa verifikasi token. Pengecekan peran per aksi juga tidak bisa jalan tanpa identitas pengguna.",
      "evidence": "F-04 (fase 1), F-05, F-06, dan F-09 \"Ekspor ... ke file CSV\" dan \"Hapus data member secara permanen\" (fase 2) muncul sebelum F-01 \"Pengecekan token di setiap request ke server\" (fase 3). Asumsi: \"Keamanan data standar: wajib login ... hak akses dicek per akun\".",
      "options": [
        {
          "label": "Wajibkan verifikasi token dan cek peran sejak endpoint pertama",
          "consequence": "Setiap endpoint langsung terlindungi dan bisa diuji dengan Firebase Auth Emulator. Tidak ada celah di masa pengembangan, jadi bisa di-deploy ke staging kapan saja dengan aman."
        },
        {
          "label": "Tunda auth tapi jangan deploy ke lingkungan publik sebelum fase 3",
          "consequence": "Pengembangan awal sedikit lebih cepat, tapi pengecekan peran harus ditambal belakangan ke semua endpoint. Risiko ada endpoint yang terlewat, dan staging tidak bisa dipakai untuk uji coba dengan data asli."
        }
      ],
      "recommended_option": "Wajibkan verifikasi token dan cek peran sejak endpoint pertama"
    },
    {
      "id": "RV-04",
      "category": "scope_creep",
      "severity": "high",
      "finding": "Fitur leaderboard dan poin member tidak berasal dari jawaban kamu, walaupun ditandai source \"user\". Fitur ini juga bertentangan dengan non-goal (member tidak login, tidak ada check-in) dan bergantung pada check-in yang tidak ada di MVP.",
      "evidence": "F-90 \"Leaderboard dan gamifikasi poin member\" dengan sub_features \"Poin per check-in\", source \"user\", depends_on []. Fitur wajib dari user hanya \"Daftar member dengan status aktif atau habis | Perpanjangan membership\". Non_goals: \"Member tidak bisa login atau punya aplikasi sendiri\" dan \"Tidak ada check-in kehadiran member\". F-90 juga dimasukkan ke phase 3 \"Notifikasi\" yang tidak ada hubungannya.",
      "options": [
        {
          "label": "Hapus F-90 dari MVP",
          "consequence": "MVP tetap fokus ke pemantauan status dan perpanjangan. Gamifikasi bisa dipertimbangkan nanti setelah check-in (R-02) dan portal member (R-05) ada."
        },
        {
          "label": "Pindahkan ke recommended_features sebagai ide lanjutan",
          "consequence": "Idenya tetap tercatat untuk versi berikutnya, dengan catatan bahwa fitur ini butuh check-in dan akun member dulu. Scope MVP tetap bersih."
        }
      ],
      "recommended_option": "Hapus F-90 dari MVP"
    },
